import { useState } from 'react';
import { variableCollections, variablesTotal } from '../data/designTokens';
import './variablesWindow.css';

// Interactive "Variables" window for the Built with Claude case. The data is generated by
// scripts/build-design-tokens.cjs (Figma snapshot + globals.css), so every count here comes from it.
// The chrome (rounded window, title bar, traffic lights) uses the same classes as the Finder-style window in
// MyToolkitSection, which is left untouched. Layout sizes live in variablesWindow.css; colours, shadows, radius and
// font sizes there are tokens.

const FolderIcon = () => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true" className="vw-folder">
    <path
      d="M2 4.2c0-.7.5-1.2 1.2-1.2h3.3l1.6 1.8h6.7c.7 0 1.2.5 1.2 1.2v6.8c0 .7-.5 1.2-1.2 1.2H3.2C2.5 14 2 13.5 2 12.8V4.2z"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinejoin="round"
    />
  </svg>
);

const swatchStyle = (name) => (name ? { background: `var(${name})` } : undefined);

function Preview({ row }) {
  switch (row.p) {
    case 'color':
      return <span className="vw-sw" style={swatchStyle(row.s)} />;
    case 'size':
      return <span className="vw-aa" style={{ fontSize: `var(${row.pv})` }}>Aa</span>;
    case 'family':
      return <span className="vw-aa" style={{ fontFamily: `var(${row.pv})` }}>Aa</span>;
    case 'weight':
      return <span className="vw-aa" style={{ fontWeight: `var(${row.pv})` }}>Aa</span>;
    case 'space':
      return <span className="vw-spc" style={{ width: `${row.pv}px` }} />;
    case 'radius':
      return <span className="vw-rad" style={{ borderTopLeftRadius: `var(${row.pv})` }} />;
    default:
      return null;
  }
}

function Row({ row }) {
  return (
    <li className="vw-row">
      <span className="vw-pv" aria-hidden="true">
        <Preview row={row} />
      </span>
      <span className="vw-fn">{row.f}</span>
      {row.c || !row.via ? (
        <span className="vw-cn">{row.c ?? '—'}</span>
      ) : (
        <span className="vw-cn" title={`No primitive variable in code. Used through the semantic variable ${row.via}.`}>
          <span aria-hidden="true">via {row.via}</span>
          <span className="vw-sr">No primitive variable in code. Used through the semantic variable {row.via}.</span>
        </span>
      )}
      <span className="vw-vl">
        {row.a ? (
          <span className="vw-alias">
            <span className="vw-sw vw-sw--s" style={swatchStyle(row.as)} aria-hidden="true" />
            {row.a}
          </span>
        ) : (
          <span className="vw-val">{row.p === 'color' ? `#${row.v}` : row.v}</span>
        )}
      </span>
    </li>
  );
}

export default function VariablesWindow({ className = '' }) {
  const [active, setActive] = useState('semantic');
  const current = variableCollections.find((c) => c.id === active);
  const listId = `vw-list-${current.id}`;

  return (
    <div
      role="group"
      aria-label={`Variables, ${variablesTotal} variables in ${variableCollections.length} collections`}
      className={`rounded-2xl overflow-hidden border border-border-subtle bg-surface-default shadow-panel ${className}`}
    >
      <div className="relative flex items-center justify-between h-12 px-4 bg-surface-subtle border-b border-border-subtle">
        <span aria-hidden="true" className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-pill bg-traffic-red" />
          <span className="w-3 h-3 rounded-pill bg-traffic-yellow" />
          <span className="w-3 h-3 rounded-pill bg-traffic-green" />
        </span>
        <p className="vw-title" aria-hidden="true">Variables</p>
      </div>

      <div className="vw-body">
        <aside className="vw-side">
          <p className="vw-side-h" id="vw-side-h">Collections</p>
          <div className="vw-cbs" role="group" aria-labelledby="vw-side-h">
            {variableCollections.map((c) => (
              <button
                key={c.id}
                type="button"
                className={`vw-cb${c.id === active ? ' vw-cb--on' : ''}`}
                aria-pressed={c.id === active}
                aria-controls={`vw-list-${c.id}`}
                onClick={() => setActive(c.id)}
              >
                <FolderIcon />
                <span className="vw-cb-n">{c.label}</span>
                <span className="vw-cb-c">{c.count}</span>
              </button>
            ))}
          </div>
        </aside>

        <div className="vw-lists">
          <div
            key={current.id}
            id={listId}
            className={`vw-list vw-list--${current.id}`}
            role="region"
            tabIndex={0}
            aria-label={`Variables, ${current.label}`}
          >
            <ul>
              {current.groups.map((g) => (
                <li key={g.label} role="presentation" className="vw-group">
                  {current.groups.length > 1 && (
                    <p className="vw-grp" role="presentation">{g.note || g.label}</p>
                  )}
                  <ul>
                    {g.rows.map((row) => (
                      <Row key={row.f} row={row} />
                    ))}
                  </ul>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}
